#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_ELEM 10
static int parent[MAX_ELEM];
static int rankv[MAX_ELEM];

static int find_set(int x) {
    if (parent[x] != x)
        parent[x] = find_set(parent[x]);
    return parent[x];
}

static void union_set(int a, int b) {
    int ra = find_set(a);
    int rb = find_set(b);
    if (ra == rb) return;
    if (rankv[ra] < rankv[rb]) {
        parent[ra] = rb;
    } else {
        parent[rb] = ra;
        if (rankv[ra] == rankv[rb])
            rankv[ra]++;
    }
}

static int valid_index(long v) {
    return v >= 0 && v < MAX_ELEM;
}

int main(int argc, char **argv) {
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }
    for (int i = 0; i < MAX_ELEM; ++i) {
        parent[i] = i;
        rankv[i] = 0;
    }
    for (int i = 1; i < argc; ) {
        const char *cmd = argv[i];
        if (cmd[0] == 'U' && strcmp(cmd, "UNION") == 0) {
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) { puts("INVALID"); i += 3; continue; }
            union_set((int)a, (int)b);
            printf("UNION %ld %ld\n", a, b);
            i += 3; continue;
        }
        if (cmd[0] == 'F' && strcmp(cmd, "FIND") == 0) {
            if (i + 1 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            if (!valid_index(a)) { puts("INVALID"); i += 2; continue; }
            int rep = find_set((int)a);
            printf("FIND %ld=%d\n", a, rep);
            i += 2; continue;
        }
        if (cmd[0] == 'C' && strcmp(cmd, "CONNECTED") == 0) {
            if (i + 2 >= argc) { puts("INVALID"); break; }
            long a = strtol(argv[i+1], NULL, 10);
            long b = strtol(argv[i+2], NULL, 10);
            if (!valid_index(a) || !valid_index(b)) { puts("INVALID"); i += 3; continue; }
            if (find_set((int)a) == find_set((int)b))
                puts("YES");
            else
                puts("NO");
            i += 3; continue;
        }
        ++i; // skip unknown token
    }
    return 0;
}
